from dsa7 import *
topic('bits', 'Bit Manipulation', 'Work directly with the binary form of numbers')
Q('Easy', 'Count Set Bits', 'Print how many 1 bits N has in binary. | Input: N. | Output: the count.', lambda s: bin(int(s)).count('1'), [L(13)], num(0, 10**9))
Q('Easy', 'Is Power of Two', 'Print YES if N is a power of two, else NO. | Input: N (N>=1). | Output: YES or NO.', lambda s: 'YES' if (lambda n: n & (n - 1) == 0)(int(s)) else 'NO', [L(16), L(18)], num(1, 3000))
Q('Easy', 'Is Odd or Even By Bit', 'Print ODD or EVEN by looking at the lowest bit. | Input: N. | Output: ODD or EVEN.', lambda s: 'ODD' if int(s) & 1 else 'EVEN', [L(7)], num(0, 10**6))
Q('Easy', 'Get Bit', 'Print bit number I (0 is the least significant) of N. | Input: N and I. | Output: 0 or 1.', lambda s: (lambda n, i: n >> i & 1)(*iv(s)), [L(10, 1)], lambda r: L(r.randint(0, 1000), r.randint(0, 12)))
Q('Easy', 'Set Bit', 'Set bit I of N to 1 and print the new number. | Input: N and I. | Output: the number.', lambda s: (lambda n, i: n | (1 << i))(*iv(s)), [L(8, 1)], lambda r: L(r.randint(0, 1000), r.randint(0, 12)))
Q('Easy', 'Clear Bit', 'Set bit I of N to 0 and print the new number. | Input: N and I. | Output: the number.', lambda s: (lambda n, i: n & ~(1 << i))(*iv(s)), [L(11, 1)], lambda r: L(r.randint(0, 1000), r.randint(0, 12)))
Q('Easy', 'XOR of Two Numbers', 'Print A xor B. | Input: A and B. | Output: the result.', lambda s: (lambda a, b: a ^ b)(*iv(s)), [L(5, 3)], two(0, 10**6))
Q('Medium', 'Single Number', 'Every number appears twice except one. Print the single one. | Input: N (odd), then N integers. | Output: the single number.', lambda s: __import__('functools').reduce(lambda a, b: a ^ b, arrs(s)), [L(5, '4 1 2 1 2')], lambda r: (lambda k, x: L(2 * k + 1, J(r.sample(x + [x[0]] * 0, 0) or (lambda l: (r.shuffle(l), l)[1])([v for v in x[:k] for _ in range(2)] + [x[k]]))))(r.randint(0, 4), r.sample(range(1, 50), 6)))
Q('Medium', 'Reverse Bits', 'Reverse the 8 lowest bits of N (0..255) and print the number. | Input: N. | Output: the result.', lambda s: int(format(int(s), '08b')[::-1], 2), [L(1)], num(0, 255))
Q('Medium', 'Hamming Distance', 'Count the bit positions where A and B differ. | Input: A and B. | Output: the count.', lambda s: bin(int(s.split()[0]) ^ int(s.split()[1])).count('1'), [L(1, 4)], two(0, 10**6))
Q('Medium', 'Missing Number', 'The array holds N distinct numbers from 0..N with one missing. Print the missing one. | Input: N, then N integers. | Output: the missing number.', lambda s: (lambda a: len(a) * (len(a) + 1) // 2 - sum(a))(arrs(s)), [L(3, '3 0 1')], lambda r: (lambda n: (lambda l: (r.shuffle(l), L(n, J(l[:-1] if False else [x for x in l if x != l[0]])) )[1] if False else (lambda m: L(n, J(r.sample([x for x in range(n + 1) if x != m], n))))(r.randint(0, n)))(0))(r.randint(1, 9)))
Q('Medium', 'Power Set XOR Sum', 'Print the sum of the XOR of all subsets of the array (the empty subset gives 0). | Input: N, then N integers. | Output: the sum.', lambda s: sum(__import__('functools').reduce(lambda a, b: a ^ b, c, 0) for m in range(len(arrs(s)) + 1) for c in itertools.combinations(arrs(s), m)), [L(3, '1 3 5')], ar(0, 9, 1, 8))
Q('Medium', 'Swap Without Temp', 'Swap A and B using XOR and print "A B" after swapping. | Input: A and B. | Output: swapped values.', lambda s: '%d %d' % (iv(s)[1], iv(s)[0]), [L(3, 9)], two(0, 1000))
Q('Medium', 'Number of Bits To Flip', 'How many bits must change to convert A into B? | Input: A and B. | Output: the count.', lambda s: bin(iv(s)[0] ^ iv(s)[1]).count('1'), [L(10, 20)], two(0, 5000))
Q('Hard', 'Two Single Numbers', 'Every number appears twice except two different ones. Print the two in ascending order. | Input: N, then N integers. | Output: the two numbers.', lambda s: J(sorted(k for k, v in Counter(arrs(s)).items() if v == 1)), [L(6, '1 2 1 3 2 5')], lambda r: (lambda x: (lambda l: (r.shuffle(l), L(len(l), J(l)))[1])([v for v in x[:3] for _ in range(2)] + x[3:5]))(r.sample(range(1, 60), 5)))
Q('Hard', 'Single Number Thrice', 'Every number appears three times except one which appears once. Print it. | Input: N, then N integers. | Output: the number.', lambda s: next(k for k, v in Counter(arrs(s)).items() if v == 1), [L(7, '2 2 3 2 5 5 5')], lambda r: (lambda x: (lambda l: (r.shuffle(l), L(len(l), J(l)))[1])([v for v in x[:3] for _ in range(3)] + [x[3]]))(r.sample(range(1, 60), 4)))
Q('Hard', 'Count Bits Up To N', 'Print the number of set bits of every number from 0 to N. | Input: N. | Output: N+1 values.', lambda s: J(bin(i).count('1') for i in range(int(s) + 1)), [L(5)], num(0, 40))
Q('Hard', 'Maximum XOR Pair', 'Print the largest value of a[i] xor a[j] over all pairs (i may equal j). | Input: N, then N integers. | Output: the maximum.', lambda s: max(x ^ y for x in arrs(s) for y in arrs(s)), [L(6, '3 10 5 25 2 8')], ar(0, 100, 1, 9))
Q('Hard', 'Subsets With XOR K', 'Count subsets (by position, including empty) whose XOR equals K. | Input: N, the array, K. | Output: the count.', lambda s: (lambda t: sum(1 for m in range(1 << t[0]) if __import__('functools').reduce(lambda a, b: a ^ b, [t[1 + i] for i in range(t[0]) if m >> i & 1], 0) == t[-1]))(iv(s)), [L(3, '1 2 3', 0)], arq(0, 7, 1, 8, 0, 7))
Q('Hard', 'Gray Code To Binary', 'Convert the Gray code number G (as a decimal integer) back to the ordinary number whose Gray code it is. | Input: G. | Output: the original number.', lambda s: (lambda g: (lambda f: f(f, g, 0))(lambda f, x, r: r if x == 0 else f(f, x >> 1, r ^ x)))(int(s)), [L(7)], num(0, 5000))

topic('math', 'Number Theory and Math', 'Divisibility, primes, GCD and modular arithmetic')
Q('Easy', 'Is Prime', 'Print YES if N is prime, else NO. | Input: N. | Output: YES or NO.', lambda s: 'YES' if (lambda n: n > 1 and all(n % d for d in range(2, int(n ** .5) + 1)))(int(s)) else 'NO', [L(17), L(18)], num(1, 10**5))
Q('Easy', 'GCD', 'Print the greatest common divisor of A and B. | Input: A and B. | Output: the GCD.', lambda s: math.gcd(*iv(s)), [L(12, 18)], two(1, 10**6))
Q('Easy', 'LCM', 'Print the least common multiple of A and B. | Input: A and B. | Output: the LCM.', lambda s: (lambda a, b: a * b // math.gcd(a, b))(*iv(s)), [L(4, 6)], two(1, 10**4))
Q('Easy', 'Count Divisors', 'Print how many positive divisors N has. | Input: N. | Output: the count.', lambda s: sum(1 for d in range(1, int(s) + 1) if int(s) % d == 0), [L(12)], num(1, 3000))
Q('Easy', 'Sum of Digits', 'Print the sum of the digits of N. | Input: N. | Output: the sum.', lambda s: sum(map(int, s.strip())), [L(1234)], num(0, 10**12))
Q('Easy', 'Reverse a Number', 'Reverse the digits of N and print the number (drop leading zeros). | Input: N. | Output: the reversed number.', lambda s: int(s.strip()[::-1]), [L(1200)], num(1, 10**9))
Q('Easy', 'Armstrong Number', 'Print YES if N equals the sum of its digits each raised to the number of digits, else NO. | Input: N. | Output: YES or NO.', lambda s: 'YES' if sum(int(c) ** len(s.strip()) for c in s.strip()) == int(s) else 'NO', [L(153), L(154)], num(1, 10000))
Q('Medium', 'Primes Up To N', 'Print all primes up to N, space separated (use a sieve). | Input: N. | Output: the primes.', lambda s: J(p for p in range(2, int(s) + 1) if all(p % d for d in range(2, int(p ** .5) + 1))), [L(20)], num(2, 300))
Q('Medium', 'Prime Factorisation', 'Print the prime factors of N in ascending order, repeated by multiplicity. | Input: N (N>=2). | Output: the factors.', lambda s: (lambda n: J((lambda f: f(f, n, 2))(lambda f, x, d: [] if x == 1 else [d] + f(f, x // d, d) if x % d == 0 else f(f, x, d + 1))))(int(s)), [L(84)], num(2, 5000))
Q('Medium', 'Modular Power', 'Print A^B mod M. | Input: A B M. | Output: the result.', lambda s: pow(*iv(s)), [L('2 10 1000')], lambda r: L('%d %d %d' % (r.randint(1, 50), r.randint(0, 40), r.randint(2, 1000))))
Q('Medium', 'Count Trailing Zeros of Factorial', 'Print the number of trailing zeros in N!. | Input: N. | Output: the count.', lambda s: (lambda n: sum(n // 5 ** k for k in range(1, 12)))(int(s)), [L(100)], num(0, 10**6))
Q('Medium', 'Perfect Numbers Up To N', 'A perfect number equals the sum of its proper divisors. Print how many exist up to N. | Input: N. | Output: the count.', lambda s: sum(1 for n in range(2, int(s) + 1) if sum(d for d in range(1, n) if n % d == 0) == n), [L(30)], num(1, 600))
Q('Medium', 'Nth Prime', 'Print the N-th prime (the 1st is 2). | Input: N. | Output: the prime.', lambda s: (lambda n: [p for p in range(2, 3000) if all(p % d for d in range(2, int(p ** .5) + 1))][n - 1])(int(s)), [L(5)], num(1, 300))
Q('Medium', 'Digital Root', 'Repeatedly sum the digits until one digit remains. Print it. | Input: N. | Output: the digit.', lambda s: (lambda n: 0 if n == 0 else 1 + (n - 1) % 9)(int(s)), [L(493193)], num(0, 10**12))
Q('Hard', 'Euler Totient', 'Print the count of integers from 1 to N that are coprime with N. | Input: N. | Output: the count.', lambda s: sum(1 for k in range(1, int(s) + 1) if math.gcd(k, int(s)) == 1), [L(36)], num(1, 3000))
Q('Hard', 'Extended GCD Combination', 'Find the smallest non-negative X such that A*X leaves remainder 1 when divided by M, or -1 if none exists. | Input: A and M. | Output: X or -1.', lambda s: (lambda a, m: next((x for x in range(m) if a * x % m == 1 % m), -1))(*iv(s)), [L(3, 11)], lambda r: L(r.randint(1, 50), r.randint(2, 60)))
Q('Hard', 'Count Primes Between', 'Print how many primes lie between A and B (inclusive). | Input: A and B (A<=B). | Output: the count.', lambda s: (lambda a, b: sum(1 for n in range(max(a, 2), b + 1) if all(n % d for d in range(2, int(n ** .5) + 1))))(*sorted(iv(s))), [L(10, 30)], two(1, 2000))
Q('Hard', 'Sum of Divisors Up To N', 'Print the sum over k=1..N of the sum of divisors of k. | Input: N. | Output: the total.', lambda s: sum(k * (int(s) // k) for k in range(1, int(s) + 1)), [L(4)], num(1, 3000))
Q('Hard', 'Chinese Remainder Smallest X', 'Find the smallest X>=0 with X mod A = R1 and X mod B = R2, or -1 if none below A*B. | Input: A R1 B R2. | Output: X or -1.', lambda s: (lambda a, r1, b, r2: next((x for x in range(a * b) if x % a == r1 and x % b == r2), -1))(*iv(s)), [L('3 2 5 3')], lambda r: L('%d %d %d %d' % ((lambda a, b: (a, r.randint(0, a - 1), b, r.randint(0, b - 1)))(r.randint(2, 12), r.randint(2, 12)))))
Q('Hard', 'Base Conversion', 'Convert the number from base A to base B (bases 2 to 16, digits 0-9 and uppercase A-F) and print it. | Input: line 1 the number, line 2 "A B". | Output: the converted number.', lambda s: (lambda t: (lambda n, a, b: (lambda v: ('0' if v == 0 else (lambda f: f(f, v))(lambda f, x: '' if x == 0 else f(f, x // b) + '0123456789ABCDEF'[x % b]))))(t[0].strip(), *map(int, t[1].split()))(int(t[0].strip(), int(t[1].split()[0]))))(s.strip().split('\n')), [L('FF', '16 2')], lambda r: (lambda a, b, v: L(format(v, {2: 'b', 8: 'o', 16: 'X', 10: 'd'}[a]), '%d %d' % (a, b)))(r.choice([2, 8, 10, 16]), r.choice([2, 8, 10, 16]), r.randint(0, 3000)))
Q('Hard', 'Count Coprime Pairs', 'Count pairs i<j whose values have GCD equal to 1. | Input: N, then N positive integers. | Output: the count.', lambda s: sum(1 for i in range(len(arrs(s))) for j in range(i + 1, len(arrs(s))) if math.gcd(arrs(s)[i], arrs(s)[j]) == 1), [L(4, '2 3 4 5')], ar(1, 30, 1, 9))
